// Authentic Quranic Uthmani Texts with offline storage and robust loader
export interface AyahItem {
  numberInSurah: number;
  text: string;
}

// Robust regex for stripping any Bismillah prefix from Ayah 1 of Surahs 2..114
export const BISMILLAH_PREFIX_REGEX = /^[\s\uFEFF\xA0]*ب[\u064B-\u065F\u0670]*س[\u064B-\u065F\u0670]*م[\u064B-\u065F\u0670]*[\s\uFEFF\xA0]+[اٱ][\u064B-\u065F\u0670]*ل[\u064B-\u065F\u0670]*ل[\u064B-\u065F\u0670]*ه[\u064B-\u065F\u0670]*[\s\uFEFF\xA0]+[اٱ][\u064B-\u065F\u0670]*ل[\u064B-\u065F\u0670]*ر[\u064B-\u065F\u0670]*ح[\u064B-\u065F\u0670]*م[\u064B-\u065F\u0670]*ن[\u064B-\u065F\u0670]*[\s\uFEFF\xA0]+[اٱ][\u064B-\u065F\u0670]*ل[\u064B-\u065F\u0670]*ر[\u064B-\u065F\u0670]*ح[\u064B-\u065F\u0670]*ي[\u064B-\u065F\u0670]*م[\u064B-\u065F\u0670]*[\s\uFEFF\xA0]*/u;

// Clean Bismillah prefix thoroughly from Ayah 1 of any surah other than Al-Fatihah
export function cleanAyahPrefix(text: string, surahNumber: number, ayahNumber: number): string {
  if (surahNumber === 1 || ayahNumber !== 1) {
    return text.trim();
  }
  return text.replace(BISMILLAH_PREFIX_REGEX, '').trim();
}

